   {((tab==="leads"&&hasMoreLeads)||(tab==="opportunities"&&hasMoreOpportunities)||(tab==="activities"&&hasMoreActivities))&&<div className="flex justify-center pt-2"><Button variant="outline" onClick={()=>void loadMore()} disabled={loadingMore}>{loadingMore?"Loading…":"Load more records"}</Button></div>}
